package com.huiqiyikang.assessment.mapper; import com.huiqiyikang.assessment.entity.ClassInviteCode; import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import java.util.*;
public interface ClassInviteCodeRepository extends BaseMapperX<ClassInviteCode>{default Optional<ClassInviteCode> findByCodeAndStatus(String code,String status){return Optional.ofNullable(selectOne(new QueryWrapper<ClassInviteCode>().eq("code",code).eq("status",status)));} default Optional<ClassInviteCode> findFirstByClassIdAndStatus(Long classId,String status){return Optional.ofNullable(selectOne(new QueryWrapper<ClassInviteCode>().eq("class_id",classId).eq("status",status).last("limit 1")));}
 /** 不看状态地按码查：code 列是 UNIQUE，生成新码时要连已失效的历史码一起避开。 */
 default Optional<ClassInviteCode> findByCode(String code){return Optional.ofNullable(selectOne(new QueryWrapper<ClassInviteCode>().eq("code",code)));}}
